SELECT D.category_code, I.product_name, CD.category_name, D.product_state, D.product_detail_code FROM tb_product_detail D JOIN tb_product_info I ON D.product_no = I.product_no JOIN tb_category_code CD ON CD.category_code = D.category_code
AND D.loginID = #{loginId}
AND D.product_state = #{productState}
ORDER BY D.product_detail_code LIMIT #{pageIndex}, #{pageSize}

